UPDATE tianquan_oauth.oauth_identity_user
SET username = #{po.username},
    display_name = #{po.displayName},
    status = #{po.status},
    failed_login_count = #{po.failedLoginCount},
    locked_until = #{po.lockedUntil},
    last_login_at = #{po.lastLoginAt},
    version = #{po.version},
    update_user_id = #{po.updateUserId},
    update_time = #{po.updateTime}
WHERE tenant_id = #{directoryPartitionId}
  AND id = #{po.id}
  AND identity_sub = #{po.identitySub}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL
